    async def bounty_tasks(
        self,
        *,
        coin_address: str | None = None,
        creator_address: str | None = None,
        cursor: str | None = None,
        expires_at_gte: str | None = None,
        expires_at_lte: str | None = None,
        facets: bool = True,
        include_banned: bool | None = None,
        lat: float | None = None,
        like_count_gte: int | None = None,
        limit: int = 24,
        lng: float | None = None,
        order: OrderDirectionParam = "desc",
        phase: Sequence[BountyPhaseParam] | None = None,
        q: str | None = None,
        radius_km: float | None = None,
        reward_mints: Sequence[str] | None = None,
        reward_total_usd_gte: float | None = None,
        reward_total_usd_lte: float | None = None,
        sort: BountySortParam = "rewardTotalUsd",
        submission_count_gte: int | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GetBountyTasksResponse:
        """Bounty tasks posted on pump.fun go, with filters for phase, reward, expiry, engagement and distance. Sorting by `distance` needs `lat` and `lng`, which go together. Pass `cursor` from the previous page for more. Costs 1 credit.

        Args:
            coin_address: Restrict to bounties on one Solana coin.
            creator_address: Bounties posted by this Solana wallet.
            cursor: `nextCursor` from the previous page; omit for the first page.
            expires_at_gte: Expiring at or after this ISO 8601 date or time, such as
                `2026-11-01T00:00:00Z`.
            expires_at_lte: Expiring at or before this ISO 8601 date or time, such
                as `2026-11-01`.
            facets: Include aggregate facet counts alongside the tasks.
            include_banned: Include moderated tasks.
            lat: Latitude for a distance search.
            like_count_gte: Minimum likes.
            limit: Maximum tasks to return.
            lng: Longitude for a distance search.
            order: Sort direction.
            phase: Lifecycle phases to return. Repeat for several. A phase is
                pump.fun's grouping of task states, not the task's `status`: an
                `OPEN` task can carry status `PENDING_RESOLUTION`. Tasks carry no
                `phase` field.
            q: Free-text search.
            radius_km: Radius in km for a distance search.
            reward_mints: Bounties paying in these Solana token mints. Repeat for
                several.
            reward_total_usd_gte: Minimum reward in USD.
            reward_total_usd_lte: Maximum reward in USD.
            sort: Ranking column.
            submission_count_gte: Minimum submissions.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.pumpfun.GetBountyTasksResponse`.
        """
        return await self._send(
            _bounty_tasks(
                coin_address=coin_address,
                creator_address=creator_address,
                cursor=cursor,
                expires_at_gte=expires_at_gte,
                expires_at_lte=expires_at_lte,
                facets=facets,
                include_banned=include_banned,
                lat=lat,
                like_count_gte=like_count_gte,
                limit=limit,
                lng=lng,
                order=order,
                phase=phase,
                q=q,
                radius_km=radius_km,
                reward_mints=reward_mints,
                reward_total_usd_gte=reward_total_usd_gte,
                reward_total_usd_lte=reward_total_usd_lte,
                sort=sort,
                submission_count_gte=submission_count_gte,
            ),
            timeout=timeout,
        )

