    async def chain_candles(
        self,
        chain: str,
        address: str,
        *,
        resolution: CandleResolutionParam,
        count: int = 200,
        measure: PriceMeasureParam = "price_usd",
        pool: str | None = None,
        to: int | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GetChainCandlesResponse:
        """OHLCV bars for a coin on any chain pump.fun trades, oldest first: Solana, the EVM chains, and HyperCore perps (`hypercore`, address = coin name such as `BTC`; perps serve `price_usd` and `price_quote` only). Prices are decimal strings. Costs 1 credit.

        Args:
            chain: See the API reference.
            address: See the API reference.
            resolution: Bar width.
            count: Bars ending at `to`.
            measure: What each bar measures. `market_cap_usd` multiplies the USD
                price by the current circulating supply.
            pool: One pool of the coin. Omit to stitch curve and AMM bars together.
            to: Unix time in milliseconds of the newest bar. Omit for now, forming
                bar included.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.pumpfun.GetChainCandlesResponse`.
        """
        return await self._send(
            _chain_candles(
                chain,
                address,
                resolution=resolution,
                count=count,
                measure=measure,
                pool=pool,
                to=to,
            ),
            timeout=timeout,
        )

