    def mint_positions(
        self,
        mint: str,
        *,
        chain: TokenChainParam | None = None,
        dust_floor_usd: float | None = None,
        include_profile: bool | None = None,
        page: int | None = None,
        page_size: int = 50,
        page_token: str | None = None,
        sort_by: MintPositionSortParam = "TOP",
        updates_limit: int | None = None,
        with_thesis: bool | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GetMintPositionsResponse:
        """Positions traders hold in a coin, with their callouts. `CLOSED_PNL` lists fully exited positions by realized PnL instead. Costs 1 credit.

        Args:
            mint: See the API reference.
            chain: `RANKED` only: chain of an EVM coin.
            dust_floor_usd: Ignore positions below this USD value. Refused with
                `RANKED` and `CLOSED_PNL`.
            include_profile: Embed each holder's full profile.
            page: Page number, from 0. Not with `RANKED`.
            page_size: Positions per page.
            page_token: `RANKED` only: `nextPageToken` from the previous page.
                pump.fun answered `RANKED` in one page (`hasMore` false) with no
                `nextPageToken` in every probe since 2026-10-08.
            sort_by: Ranking column.
            updates_limit: Author updates per callout (pump.fun's default 5).
            with_thesis: Only positions carrying a written thesis. `RANKED` and
                `CLOSED_PNL` need `true`.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.pumpfun.GetMintPositionsResponse`.
        """
        return self._send(
            _mint_positions(
                mint,
                chain=chain,
                dust_floor_usd=dust_floor_usd,
                include_profile=include_profile,
                page=page,
                page_size=page_size,
                page_token=page_token,
                sort_by=sort_by,
                updates_limit=updates_limit,
                with_thesis=with_thesis,
            ),
            timeout=timeout,
        )

