    def search_coins(
        self,
        *,
        search_term: str,
        complete: bool | None = None,
        creator: str | None = None,
        include_nsfw: bool = False,
        limit: int = 10,
        max_age_seconds: int | None = None,
        min_age_seconds: int | None = None,
        offset: int = 0,
        order: CoinSortDirectionParam = "DESC",
        sort: CoinSortParam = "market_cap",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> list[SearchedCoin]:
        """Search coins on every chain by name, symbol or address. For coins created in the last 7 days, set `max_age_seconds=604800`. Costs 1 credit.

        Args:
            search_term: Free-text search term.
            complete: `true` keeps graduated coins only, `false` bonding-curve coins
                only.
            creator: Only coins launched by this wallet, Solana or EVM (0x).
            include_nsfw: Include coins flagged not-safe-for-work.
            limit: Maximum coins to return.
            max_age_seconds: Only coins at most this many seconds old.
            min_age_seconds: Only coins at least this many seconds old.
            offset: Rows to skip.
            order: Deprecated: pump.fun does not order search results by this
                column, though a value other than the default can change which coins
                come back.
            sort: Deprecated: pump.fun does not order search results by this column,
                though a value other than the default can change which coins come
                back.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A list of :class:`~tapline.pumpfun.SearchedCoin`.
        """
        return self._send(
            _search_coins(
                search_term=search_term,
                complete=complete,
                creator=creator,
                include_nsfw=include_nsfw,
                limit=limit,
                max_age_seconds=max_age_seconds,
                min_age_seconds=min_age_seconds,
                offset=offset,
                order=order,
                sort=sort,
            ),
            timeout=timeout,
        )

