    def user_portfolio(
        self,
        address: str,
        *,
        chain: NonMonadChainParam | None = None,
        filter: PortfolioFilterParam = "OPEN",
        filter_spam: bool | None = None,
        page: int = 0,
        page_size: int = 100,
        sort_by: PortfolioSortParam = "POSITION_SIZE",
        spam_only: bool | None = None,
        total_only: bool | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GetUserPortfolioResponse:
        """A wallet's open or closed positions with net PnL, across Solana and its linked EVM wallets. Takes a wallet, a pump.fun user id or a squad id. Costs 1 credit.

        Args:
            address: See the API reference.
            chain: Only positions on this chain. pump.fun keeps no Monad portfolio.
            filter: Which positions to return.
            filter_spam: Drop positions pump.fun groups as spam before paging.
            page: Zero-based page index.
            page_size: Positions per page.
            sort_by: Ranking column.
            spam_only: Return only the spam group. Cannot be combined with
                `filter_spam`.
            total_only: Return the summary only (position count), without positions.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.pumpfun.GetUserPortfolioResponse`.
        """
        return self._send(
            _user_portfolio(
                address,
                chain=chain,
                filter=filter,
                filter_spam=filter_spam,
                page=page,
                page_size=page_size,
                sort_by=sort_by,
                spam_only=spam_only,
                total_only=total_only,
            ),
            timeout=timeout,
        )

